func (td *TableDebouncer) drainRemainingOnStop() {
	// BẮT BUỘC chiếm td.sem trước tiên để đợi mẻ in-flight đang chạy hoàn tất 100%,
	// giữ tuyệt đối bất biến concurrencyLimit = 1 và thứ tự FIFO.
	td.sem <- struct{}{}
	defer func() { <-td.sem }()

	for {
		select {
		case batch := <-td.flushCh:
			td.runBatchWithShutdownTimeout(batch)
		default:
			td.mu.Lock()
			if td.idleTimer != nil {
				td.idleTimer.Stop()
				td.idleTimer = nil
			}
			if td.maxTimer != nil {
				td.maxTimer.Stop()
				td.maxTimer = nil
			}
			tasks := td.tasks
			td.tasks = nil
			td.pendingEvents = 0
			td.mu.Unlock()

			td.runBatchWithShutdownTimeout(tasks)
			return
		}
	}
}

